import {PRODUCT_PHOTOS} from './product-photos.js?v=23.0.0';
import {paintPerson} from './sprites.js?v=34.0.0';
import {equippedLook,slotForProduct} from './engine.js?v=34.0.0';
// A presentation only: the engine applies the action once before this scene starts.
export class ActivityScene{
 constructor(canvas,state,kind,done){Object.assign(this,{canvas,state,kind,done,elapsed:0,last:0,alive:true});this.ctx=canvas.getContext('2d');requestAnimationFrame(t=>this.frame(t));}
 destroy(){this.alive=false;}
 frame(now){if(!this.alive)return;const dt=this.last?Math.min(.05,(now-this.last)/1000):0;this.last=now;if(!document.hidden)this.elapsed+=dt;const caption=this.canvas.closest('section')?.querySelector('[data-activity-caption]'),stage=this.elapsed<.9?'Walking into a little moment…':this.kind==='rest'?'Sitting on the bench and resting.':this.kind==='icecream'?'Sitting and enjoying an ice cream cone.':this.kind==='drink'?'Sitting and sipping a drink.':this.kind==='eat'?'Sitting down to enjoy a meal.':this.kind==='try'?'Turning in the mirror to try this real product.':this.kind==='window'?'Looking closely at a real product in the shop window.':this.kind==='chat'?'Sharing a friendly moment with a mall regular.':'Enjoying this activity. The clock is paused.';if(caption&&caption.textContent!==stage)caption.textContent=stage;this.draw();if(this.elapsed>(this.state.preferences.reducedMotion?.6:4.2)){this.alive=false;this.done();return;}requestAnimationFrame(t=>this.frame(t));}
 draw(){const c=this.ctx,t=this.elapsed;c.setTransform(this.canvas.width/800,0,0,this.canvas.height/400,0,0);c.clearRect(0,0,800,400);const rect=(x,y,w,h,col)=>{c.fillStyle=col;c.fillRect(x,y,w,h);};rect(0,0,800,400,'#e7eddd');rect(0,270,800,130,'#dbcfb2');for(let i=0;i<8;i++){rect(i*115,280,2,120,'#cabd9d');rect(i*130+10,70,38,135,'#c8dab6');}rect(65,200,670,15,'#789d75');for(let i=0;i<9;i++){c.fillStyle=['#dda68b','#c6a2bb','#e6ce7b'][i%3];c.beginPath();c.arc(100+i*75,190+Math.sin(i)*8,10,0,7);c.fill();}
 if(this.kind==='window'){rect(325,85,340,160,'#b6cec4');rect(335,95,320,140,'#dce9d9');rect(490,95,5,140,'#799b89');rect(335,225,320,10,'#bb9d72');if(this.previewProduct&&PRODUCT_PHOTOS[this.previewProduct.id]){if(!this.photo){this.photo=new Image();this.photo.src=PRODUCT_PHOTOS[this.previewProduct.id].path;}if(this.photo.complete&&this.photo.naturalWidth){const k=Math.min(240/this.photo.naturalWidth,125/this.photo.naturalHeight);c.drawImage(this.photo,495-this.photo.naturalWidth*k/2,158-this.photo.naturalHeight*k/2,this.photo.naturalWidth*k,this.photo.naturalHeight*k);}}c.fillStyle='#567861';c.font='600 18px Arial';c.textAlign='center';c.fillText(this.previewProduct?.brand||'The window edit',495,76);}
 if(this.kind==='chat'){c.save();c.translate(535,290);c.scale(2.45,2.45);paintPerson(c,0,0,{color:this.previewProduct?.color||'#b789ad',facing:'left',time:t});c.restore();rect(425,105,150,52,'#fff8df');c.fillStyle='#8b8b6b';c.font='28px Georgia';c.textAlign='center';c.fillText(t%1>.5?'···':'♡',500,140);}
 const resting=this.kind==='rest',seating=resting||['eat','drink','icecream','cinema','carousel'].includes(this.kind),approach=Math.min(1,t/.9),x=this.kind==='bridge'||this.kind==='artwalk'?170+t*105:this.kind==='carousel'&&t>=.9?400+Math.cos((t-.9)*1.4)*100:170+approach*220,pose=t<.9?'stand':this.kind==='cinema'||this.kind==='carousel'?'sit':seating?this.kind:'stand';
 if(this.kind==='bridge'){rect(0,285,800,20,'#b39e77');rect(0,218,800,8,'#8b9c74');for(let i=0;i<9;i++)rect(i*100,218,7,70,'#8b9c74');}
 if(this.kind==='cinema'){rect(70,65,200,125,'#648882');rect(81,76,178,103,'#a2c6bd');c.fillStyle='#efdeae';c.beginPath();c.arc(170+Math.sin(t)*30,127,25,0,7);c.fill();}
 if(this.kind==='carousel'){c.fillStyle='#ce8e81';c.beginPath();c.moveTo(250,170);c.lineTo(400,65);c.lineTo(550,170);c.fill();rect(250,170,300,12,'#e6bd77');rect(395,100,10,190,'#bc9f5e');for(let i=0;i<4;i++){const a=t+i*Math.PI/2,px=400+Math.cos(a)*120;rect(px,185,5,85,'#b89c63');rect(px-18,255+Math.sin(a)*10,38,13,'#faf0d2');}}
 if(this.kind==='flowers'){rect(450,240,130,10,'#b3a17b');for(let i=0;i<5;i++){rect(465+i*20,206-Math.sin(t+i)*4,3,35,'#73966b');c.fillStyle=['#d99e9b','#c39ab5','#e2c373'][i%3];c.beginPath();c.arc(467+i*20,207-Math.sin(t+i)*4,9,0,7);c.fill();}}
 if(this.kind==='try'){rect(160,72,190,240,'#bba982');rect(173,84,164,216,'#cadbd0');rect(185,95,8,195,'#edf3e3');}
 const look=equippedLook(this.state),slot=this.kind==='try'?slotForProduct(this.previewProduct):null;if(slot)look[slot]=this.previewProduct;
 if(seating&&this.kind!=='carousel'){rect(338,260,140,12,'#a37c50');rect(342,228,132,12,'#b48c60');rect(348,272,8,40,'#547967');rect(460,272,8,40,'#547967');}
 if(this.kind==='eat'||this.kind==='drink'||this.kind==='icecream'){rect(490,238,75,9,'#c0a77c');rect(523,247,8,64,'#9c835e');}
 c.save();if(this.kind==='carousel'&&t>=.9){rect(x-23,280+Math.sin(t*3)*6,46,12,'#fff0d3');rect(x+10,268+Math.sin(t*3)*6,13,18,'#fff0d3');}c.translate(x,this.kind==='carousel'&&t>=.9?280+Math.sin(t*3)*6:290);c.scale(2.45,2.45);paintPerson(c,0,0,{appearance:this.state.appearance,equipment:look,player:true,moving:t<.9||this.kind==='bridge'||this.kind==='artwalk',facing:this.kind==='try'?['down','right','up','left'][Math.floor(t)%4]:t<.9||this.kind==='bridge'||this.kind==='artwalk'?'right':'down',distance:t*130,pose,time:t,reduced:this.state.preferences.reducedMotion});c.restore();
 c.fillStyle='#486b5a';c.textAlign='center';c.font='600 22px Georgia';c.fillText(resting?'A quiet moment between shops.':this.kind==='icecream'?'A little scoop of happiness.':this.kind==='drink'?'Coffee, shade, and a slower moment.':this.kind==='eat'?'A proper break for lunch.':this.kind==='try'?'A turn in the mirror. A look that feels like you.':this.kind==='carousel'?'A little turn beneath the lights.':this.kind==='flowers'?'Make something lovely between shops.':this.kind==='cinema'?'Settle in for a little cinema break.':this.kind==='window'?'A closer look before you choose.':this.kind==='chat'?'A familiar face. A new little conversation.':'A new little memory.',400,45);
 rect(280,361,240,6,'#bbccb2');rect(280,361,240*Math.min(1,t/4.2),6,'#5e9072');}
}
